def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    twos, verticals = set(), set()

    # Color 2: a five-cell horizontal bar, anchored at its right endpoint.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                for x in range(c - 4, c + 1):
                    if 0 <= x < w:
                        twos.add((r, x))
                        out[r][x] = 2 if x == c or x == c - 4 else 5

    # Color 3: four cells downward, with matching endpoints.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                for y in range(r, r + 4):
                    if y < h:
                        verticals.add((y, c))
                        out[y][c] = 3 if y == r or y == r + 3 else 5

    # Color 6: seven cells upward, with matching endpoints.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                for y in range(r - 6, r + 1):
                    if y >= 0:
                        verticals.add((y, c))
                        out[y][c] = 6 if y == r or y == r - 6 else 5

    # Crossings between the horizontal 2-bar and a vertical bar produce
    # a 4 and a diagonal trail down-left.
    crossings = twos & verticals
    for r, c in crossings:
        out[r][c] = 4
        y, x = r + 1, c - 1
        while y < h and x >= 0:
            out[y][x] = 4
            y += 1
            x -= 1

    # Color 1: a short rightward bar with a raised endpoint.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                out[r][c] = 1
                for x in (c + 1, c + 2):
                    if x < w:
                        out[r][x] = 5
                if r > 0 and c + 2 < w:
                    out[r - 1][c + 2] = 1

    return out
